<template>
  <div class="project-entry-actions" :class="{ 'has-pitch-deck': projectId === 'cathayflex' }" @keydown.stop>
    <component v-if="destination" :is="isExternalDestination ? 'a' : 'router-link'"
      v-bind="isExternalDestination ? { href: destination, target: '_blank', rel: 'noopener' } : { to: destination }"
      class="resource-action project-entry-primary project-detail-link">
      <span>Explore the project</span>
      <svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 10h14m-5-5 5 5-5 5" /></svg>
    </component>
    <CathayFlexDeck v-if="projectId === 'cathayflex'" />
    <div class="project-entry-secondary">
      <GitHubRepoLink v-for="link in resources" :key="link.url" :href="link.url" :label="link.label" :icon-class="link.iconClass || 'fab fa-github'" compact />
      <button v-if="projectId === 'searchstory'" type="button" class="resource-action compose-view-entry" @click="openView"><span>Compose a <AiViewTerm /></span></button>
      <GalleryEntryLink v-if="projectId === 'searchstory'" />
      <ProjectArchitecture v-else-if="isSlidePoise" :project-id="projectId" />
    </div>
  </div>
</template>

<script>
import GitHubRepoLink from './GitHubRepoLink.vue';
import ProjectArchitecture from './ProjectArchitecture.vue';
import GalleryEntryLink from './GalleryEntryLink.vue';
import AiViewTerm from './AiViewTerm.vue';
import CathayFlexDeck from './CathayFlexDeck.vue';
import { projectById, projectResourceLinks } from '../../data/projects';
import { projectWebsiteTarget } from '../../utils/viewSourceTarget';
import '../../assets/css/resource-action.css';

export default {
  name: 'ProjectEntryActions',
  components: { GitHubRepoLink, ProjectArchitecture, GalleryEntryLink, AiViewTerm, CathayFlexDeck },
  props: { projectId: { type: String, required: true } },
  computed: {
    isSlidePoise() { return this.projectId === 'slidepoise'; },
    isExternalDestination() { return /^https?:\/\//.test(this.destination); },
    destination() {
      const route = projectById(this.projectId)?.route;
      return route && route !== '/projects' ? (projectWebsiteTarget(route)?.href || route) : '';
    },
    resources() { return projectResourceLinks[this.projectId] || []; }
  },
  methods: { openView() { window.dispatchEvent(new CustomEvent('open-site-view')); } },
};
</script>

