.project-entry-actions.has-pitch-deck > .cathay-deck-entry { grid-column: 1; grid-row: 2; }
.project-entry-actions.has-pitch-deck > .project-entry-secondary { grid-column: 2; grid-row: 1; }
.project-entry-actions .resource-action { height: 44px; min-height: 44px; padding: 0; font-size: 13px; line-height: 20px; }
.project-entry-actions .project-entry-primary { --entry-hover-ink: #191817; --entry-highlight: rgb(139 122 86 / 13%); margin-right: auto; color: #4f4d49; }
.project-entry-primary > span { text-decoration: underline; text-decoration-color: rgb(128 128 120 / 45%); text-underline-offset: 5px; text-decoration-thickness: 1px; background-image: linear-gradient(var(--entry-highlight), var(--entry-highlight)); background-position: 0 100%; background-repeat: no-repeat; background-size: 100% 0; transition: background-size 180ms cubic-bezier(.23, 1, .32, 1); }
.project-entry-primary svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.25; stroke-linecap: round; stroke-linejoin: round; transition: transform 180ms cubic-bezier(.23, 1, .32, 1); }
.project-entry-actions .project-entry-primary::before { display: none; }
.project-entry-primary:focus-visible { color: var(--entry-hover-ink); }
.project-entry-primary:focus-visible > span { background-size: 100% .5em; }
.project-entry-primary:focus-visible svg { transform: translateX(3px); }
body.dark-mode .project-entry-actions .project-entry-primary { --entry-hover-ink: #f4f1ec; --entry-highlight: rgb(214 195 155 / 16%); color: #cfcbc5; }
@media (hover: hover) and (pointer: fine) {
  .project-entry-actions .project-entry-primary:hover,
  .timeline-event:hover:not(:has(a:hover, button:hover)) .project-entry-primary,
  .collection-detail-navigable:hover:not(:has(a:hover, button:hover)) .project-entry-primary { color: var(--entry-hover-ink); }
  .project-entry-primary:hover > span,
  .timeline-event:hover:not(:has(a:hover, button:hover)) .project-entry-primary > span,
  .collection-detail-navigable:hover:not(:has(a:hover, button:hover)) .project-entry-primary > span { background-size: 100% .5em; }
  .project-entry-primary:hover svg,
  .timeline-event:hover:not(:has(a:hover, button:hover)) .project-entry-primary svg,
  .collection-detail-navigable:hover:not(:has(a:hover, button:hover)) .project-entry-primary svg { transform: translateX(3px); }
}
.project-entry-secondary { display: flex; flex-wrap: wrap; align-items: center; gap: 0 28px; }
.project-entry-secondary > .project-architecture { display: flex; }
