@media (max-width: 600px) {
  .project-entry-actions.has-pitch-deck { grid-template-columns: 1fr; }
  .project-entry-actions.has-pitch-deck > .project-entry-secondary { grid-column: 1; grid-row: 3; }
  .project-entry-actions { display: grid; gap: 0; }
  .project-entry-secondary { gap: 0 24px; }
}
@media (prefers-reduced-motion: reduce) { .project-entry-primary > span, .project-entry-primary svg { transition: none; }.project-entry-primary:focus-visible svg { transform: none; } }
</style>
